import { MakeLogicType, actions, connect, kea, path, reducers, selectors } from 'kea'

import { toolsLogic } from 'scenes/tools/toolsLogic'
import { ToolGroup, groupTools, toolMatchesSearch } from 'scenes/tools/toolsUtils'

import { FileSystemImport } from '~/queries/schema/schema-general'

import { todayRecentsLogic } from './todayRecentsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayToolsLogicValues {
    recentToolHrefs: string[] // todayRecentsLogic
    tools: FileSystemImport[] // toolsLogic
    recentTools: FileSystemImport[]
    search: string
    toolGroups: ToolGroup[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayToolsLogicActions {
    setSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayToolsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        toolGroups: (tools: FileSystemImport[], search: string) => ToolGroup[]
        recentTools: (recentToolHrefs: string[], tools: FileSystemImport[], search: string) => FileSystemImport[]
    }
}

export type todayToolsLogicType = MakeLogicType<
    todayToolsLogicValues,
    todayToolsLogicActions,
    Record<string, any>,
    todayToolsLogicMeta
>

export const todayToolsLogic = kea<todayToolsLogicType>([
    path(['layout', 'today', 'todayToolsLogic']),
    connect(() => ({ values: [toolsLogic, ['tools'], todayRecentsLogic, ['recentToolHrefs']] })),
    actions({ setSearch: (search: string) => ({ search }) }),
    reducers({ search: ['', { setSearch: (_, { search }) => search }] }),
    selectors({
        toolGroups: [
            (s) => [s.tools, s.search],
            (tools: FileSystemImport[], search: string): ToolGroup[] => groupTools(tools, search),
        ],
        recentTools: [
            (s) => [s.recentToolHrefs, s.tools, s.search],
            (hrefs: string[], tools: FileSystemImport[], search: string): FileSystemImport[] =>
                hrefs
                    .flatMap((href) => tools.find((tool) => tool.href === href) ?? [])
                    .filter((tool) => toolMatchesSearch(tool, search)),
        ],
    }),
])
